val appVersion: String = providers.gradleProperty("whalerein.appVersion").getOrElse("0.1.0")
val appVersionCode: Int = providers.gradleProperty("whalerein.versionCode").getOrElse("1").toInt()

// Release signing comes from the environment or Gradle properties. A missing
// keystore leaves the release variant unsigned rather than silently using a
// debug identity; local test signing is generated by scripts/gen-test-keystore.sh.
val releaseStore = providers.environmentVariable("WHALEREIN_ANDROID_KEYSTORE")
    .orElse(providers.gradleProperty("whalerein.android.keystore"))
    .orNull
val releaseStorePassword = providers.environmentVariable("WHALEREIN_ANDROID_KEYSTORE_PASSWORD")
    .orElse(providers.gradleProperty("whalerein.android.keystorePassword"))
    .orNull
val releaseKeyAlias = providers.environmentVariable("WHALEREIN_ANDROID_KEY_ALIAS")
    .orElse(providers.gradleProperty("whalerein.android.keyAlias"))
    .orNull
val releaseKeyPassword = providers.environmentVariable("WHALEREIN_ANDROID_KEY_PASSWORD")
    .orElse(providers.gradleProperty("whalerein.android.keyPassword"))
    .orNull

android {
    namespace = "com.whalerein.android"
    compileSdk = 37
    compileSdkMinor = 2

    defaultConfig {
        applicationId = "com.whalerein.android"
        minSdk = 31
        targetSdk = 37
        versionCode = appVersionCode
        versionName = appVersion
        testInstrumentationRunner = "androidx.test.runner.AndroidJUnitRunner"
        ndk {
            abiFilters += "arm64-v8a"
        }
        buildConfigField("String", "APP_VERSION", "\"$appVersion\"")
    }

    flavorDimensions += "services"
    productFlavors {
        // Both channels share one application ID and version sequence.
        create("gms") {
            dimension = "services"
        }
        create("noGms") {
            dimension = "services"
        }
    }

    signingConfigs {
        if (releaseStore != null) {
            create("release") {
                storeFile = file(releaseStore)
                storePassword = releaseStorePassword
                keyAlias = releaseKeyAlias
                keyPassword = releaseKeyPassword
            }
        }
    }

    buildTypes {
        release {
            isMinifyEnabled = true
            isShrinkResources = true
            proguardFiles(
                getDefaultProguardFile("proguard-android-optimize.txt"),
                "proguard-rules.pro",
            )
            signingConfig = signingConfigs.findByName("release")
        }
        debug {
            applicationIdSuffix = ".debug"
            // The Linux CI emulator is x86_64; release stays arm64-only.
            ndk {
                abiFilters += "x86_64"
            }
        }
    }

    lint {
        // AGP 9.5.2's lint-vital analyzer crashes on a Kotlin property symbol in
        // this project ("Unexpected owner function: null"), which blocks release
        // packaging. Release lint stays a separate explicit check
        // (`./gradlew :app:lintNoGmsRelease`) instead of a packaging side effect.
        checkReleaseBuilds = false
    }

    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }

    buildFeatures {
        compose = true
        buildConfig = true
    }

    packaging {
        jniLibs {
            useLegacyPackaging = false
        }
        resources {
            excludes += "/META-INF/{AL2.0,LGPL2.1}"
        }
    }

    testOptions {
        unitTests.isIncludeAndroidResources = true
    }
}

// Compose UI test 1.14.0-alpha01 requires concurrent-futures 1.2.0 while the
// app's strict catalog resolution still pins 1.1.0. Keep one version for the
// instrumentation runtime; no product dependency is added.
configurations.configureEach {
    resolutionStrategy {
        force("androidx.concurrent:concurrent-futures:1.2.0")
        // Keep the Compose UI/test/foundation set on the BOM's stable release.
        // Without this, an instrumentation-only transitive request upgrades
        // `ui` to 1.14.0-alpha01 while foundation stays 1.13.0, producing a
        // runtime NoSuchFieldError inside Draggable.
        force(
            "androidx.compose.ui:ui:1.13.0",
            "androidx.compose.ui:ui-android:1.13.0",
            "androidx.compose.ui:ui-test:1.13.0",
            "androidx.compose.ui:ui-test-android:1.13.0",
